<?php require_once '../config/db.php';require_once '../includes/auth.php';require_role('admin');$rows=$pdo->query("SELECT m.*,s.name subject_name,u.name uploader FROM materials m JOIN subjects s ON s.id=m.subject_id JOIN users u ON u.id=m.uploaded_by ORDER BY m.id DESC")->fetchAll();$page_title='Materials';$css_path='../assets/css/style.css';$home_path='dashboard.php';$logout_path='../logout.php';$role='admin';include '../includes/header.php';?><div class="layout"><?php include '../includes/sidebar.php';?><h1 class="page-title">Materials</h1><div class="table-card"><table><thead><tr><th>Title</th><th>Subject</th><th>Type</th><th>Uploaded By</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['subject_name'])?></td><td><?=e(ucwords(str_replace('_',' ',$r['material_type'])))?></td><td><?=e($r['uploader'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></div></main></div><?php include '../includes/footer.php';?>